INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 13, 'theory', 'Quiz: classes and traits');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 13, 0, 'What replaces inheritance from Python in Rust?', '["the extends! macro", "composition (a struct inside a struct) and traits", "the super keyword", "nothing: inheritance exists"]', 1, 'Structs don''t inherit: shared behavior goes into a trait, and data is assembled through composition.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 13, 1, 'What do you need to implement for the + operator to work on your type?', '["the __add__ method", "the operator! macro", "nothing: plus always works", "the std::ops::Add trait"]', 3, 'Operators are traits from std::ops; the result type is written in the associated type Output.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 13, 2, 'What corresponds to __str__ from Python?', '["fmt::Display", "PartialEq", "Iterator", "Debug generated through derive"]', 0, 'Display is output for the user ({}), Debug is for debugging ({:?}); once you implement Display, you get to_string().');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 13, 3, 'How do you put values of different structs implementing one trait into a single vector?', '["Vec<impl Trait>", "Vec<Trait>", "Vec<Box<dyn Trait>>", "Vec<enum>, and no other way"]', 2, 'dyn trait objects are called through a method table, so the types can differ.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 13, 4, 'Why is the newtype pattern needed?', '["to implement a foreign trait for a foreign type through your own wrapper", "to inherit fields", "to speed up compilation", "to copy values"]', 0, 'The coherence rule forbids a foreign trait for a foreign type; a one-field wrapper is your own type, so the trait can be implemented.');
